const CACHE='nunya-v5.4.0';
const FILES=['./','./index.html','./runtime/academy.bundle.js','./runtime/academy.bundle.css','./boot-guard.js','./data/ui-academy.json','./data/ui-assessment.json','./data/assessment-questions.json','./data/paths/index.json','./data/careers_togo.json','./data/abroad_guides.json','./data/opportunities.json','./data/school_pilot.json','./data/learning_guides.json','./data/togo_projects.json','./data/togo_platforms.json','./js-worker.js','./python-worker.js','./coding-python-worker.js','./data/curriculum/index.json','./data/curriculum/search.json','./data/decouverte/index.json','./runtime/discovery-views.js','./icon.svg','./icon-192.png','./icon-512.png','./manifest.webmanifest','./guide-public.html','./data/skill_catalog.json','./data/skill_courses.json','./vendor/katex.min.js','./vendor/katex.min.css',...['KaTeX_Main-Regular.woff2','KaTeX_Math-Italic.woff2','KaTeX_Size1-Regular.woff2','KaTeX_AMS-Regular.woff2'].map(x=>'./vendor/fonts/'+x)].flatMap(f=>/\.(js|css)$/.test(f)?[f,f+'?v=5.4.0']:[f]);
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(FILES)).then(()=>self.skipWaiting()))});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>/^nunya-v[0-9]/.test(k)&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()))});
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||new URL(event.request.url).origin!==self.location.origin)return;if(event.request.mode==='navigate'){event.respondWith(fetch(event.request).then(response=>{if(response.ok){const copy=response.clone();caches.open(CACHE).then(cache=>cache.put('./index.html',copy))}return response}).catch(()=>caches.open(CACHE).then(cache=>cache.match('./index.html'))));return}event.respondWith(caches.match(event.request).then(cached=>cached||fetch(event.request).then(response=>{if(response.ok){const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,copy))}return response})).catch(()=>Response.error()))});
self.addEventListener('message',event=>{if(event.data?.type==='CACHE_OFFLINE')event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(FILES)).then(()=>event.ports[0]?.postMessage({ok:true})).catch(()=>event.ports[0]?.postMessage({ok:false})))});
